Create Outbound Shipment.code:
// Create an outbound shipment (e.g. district store -> health facility).
insertOutboundShipment({
  // Name id of the receiving facility.
  otherPartyId: $.data.facilityNameId,
  // Store the stock is shipped from.
  storeId: $.data.storeId,
});

Update Outbound Shipment Status.code:
// Update the status of an existing outbound shipment.
upsertOutboundShipment({
  storeId: $.data.storeId,
  input: {
    updateOutboundShipments: [
      {
        id: $.data.shipmentId,
        // e.g. 'PICKED', 'SHIPPED'
        status: 'PICKED',
      },
    ],
  },
});

Register Patient.code:
// Register a patient (e.g. from a community health app) in Open mSupply.
query(
  // 1) GraphQL mutation.
  `mutation insertPatient($storeId: String!, $input: InsertPatientInput!) {
    insertPatient(storeId: $storeId, input: $input) {
      ... on PatientNode { id code firstName lastName }
    }
  }`,
  // 2) Variables.
  {
    storeId: $.data.storeId,
    input: {
      id: $.data.patientUuid,
      code: $.data.nationalId,
      firstName: $.data.firstName,
      lastName: $.data.lastName,
      gender: 'FEMALE',
      dateOfBirth: $.data.dateOfBirth, // 'YYYY-MM-DD'
      phone: $.data.phone,
    },
  }
);

Create Request Requisition.code:
// Create a request requisition to order stock from a supplier store.
query(
  // 1) GraphQL mutation.
  `mutation insertRequestRequisition($storeId: String!, $input: InsertRequestRequisitionInput!) {
    insertRequestRequisition(storeId: $storeId, input: $input) {
      ... on RequisitionNode { id requisitionNumber status }
      ... on InsertRequestRequisitionError { error { description } }
    }
  }`,
  // 2) Variables.
  {
    storeId: $.data.storeId,
    input: {
      id: $.data.requisitionUuid,
      // Name id of the supplying store.
      otherPartyId: $.data.supplierNameId,
      maxMonthsOfStock: 3,
      minMonthsOfStock: 1,
      theirReference: $.data.orderReference,
      comment: 'Monthly ARV resupply',
    },
  }
);

Create Inbound Shipment.code:
// Create an inbound shipment for stock arriving from a supplier.
query(
  // 1) GraphQL mutation.
  `mutation insertInboundShipment($storeId: String!, $input: InsertInboundShipmentInput!) {
    insertInboundShipment(storeId: $storeId, input: $input) {
      ... on InvoiceNode { id invoiceNumber status }
      ... on InsertInboundShipmentError { error { description } }
    }
  }`,
  // 2) Variables.
  {
    storeId: $.data.storeId,
    input: {
      id: $.data.shipmentUuid,
      otherPartyId: $.data.supplierNameId,
      theirReference: $.data.deliveryNoteNumber,
      comment: 'Received from national medical stores',
    },
  }
);

Get Items With Stats.code:
// Get catalogue items with stock-on-hand and consumption stats.
getItemsWithStats({
  // Field to sort by.
  key: 'name',
  // Store to report on.
  storeId: $.data.storeId,
});

Get Stock On Hand.code:
// Get available stock lines for a store, e.g. for a stock dashboard.
query(
  // 1) GraphQL query.
  `query stockLines($storeId: String!, $filter: StockLineFilterInput, $page: PaginationInput) {
    stockLines(storeId: $storeId, filter: $filter, page: $page) {
      ... on StockLineConnector {
        totalCount
        nodes { id itemId itemName batch expiryDate packSize availableNumberOfPacks }
      }
    }
  }`,
  // 2) Variables.
  {
    storeId: $.data.storeId,
    filter: { isAvailable: true },
    page: { first: 500, offset: 0 },
  }
);

Find Expiring Stock.code:
// Find batches expiring in the next 90 days (for redistribution alerts).
query(
  // 1) GraphQL query.
  `query stockLines($storeId: String!, $filter: StockLineFilterInput, $sort: [StockLineSortInput!]) {
    stockLines(storeId: $storeId, filter: $filter, sort: $sort) {
      ... on StockLineConnector {
        nodes { itemName batch expiryDate availableNumberOfPacks }
      }
    }
  }`,
  // 2) Variables.
  {
    storeId: $.data.storeId,
    filter: { expiryDate: { beforeOrEqualTo: $.data.expiryCutoff } }, // 'YYYY-MM-DD'
    sort: [{ key: 'expiryDate', desc: false }],
  }
);

Find Patient By Code.code:
// Find a patient by code before creating a duplicate.
query(
  // 1) GraphQL query.
  `query patients($storeId: String!, $filter: PatientFilterInput) {
    patients(storeId: $storeId, filter: $filter) {
      ... on PatientConnector {
        totalCount
        nodes { id code firstName lastName dateOfBirth phone }
      }
    }
  }`,
  // 2) Variables.
  {
    storeId: $.data.storeId,
    filter: { code: { equalTo: $.data.nationalId } },
  }
);

List Sent Requisitions.code:
// List requisitions that have been sent to suppliers.
query(
  // 1) GraphQL query.
  `query requisitions($storeId: String!, $filter: RequisitionFilterInput) {
    requisitions(storeId: $storeId, filter: $filter) {
      ... on RequisitionConnector {
        totalCount
        nodes { id requisitionNumber type status otherPartyName sentDatetime }
      }
    }
  }`,
  // 2) Variables.
  {
    storeId: $.data.storeId,
    filter: { status: { equalTo: 'SENT' } },
  }
);

Get Temperature Breaches.code:
// Get unacknowledged cold-chain breaches (e.g. to alert a vaccine officer).
query(
  // 1) GraphQL query.
  `query temperatureBreaches($storeId: String!, $filter: TemperatureBreachFilterInput) {
    temperatureBreaches(storeId: $storeId, filter: $filter) {
      ... on TemperatureBreachConnector {
        nodes {
          id type startDatetime endDatetime maxOrMinTemperature
          sensor { name serial }
          location { name }
        }
      }
    }
  }`,
  // 2) Variables.
  {
    storeId: $.data.storeId,
    filter: { unacknowledged: true },
  }
);

List Suppliers.code:
// List supplier names visible to a store.
query(
  // 1) GraphQL query.
  `query names($storeId: String!, $filter: NameFilterInput) {
    names(storeId: $storeId, filter: $filter) {
      ... on NameConnector {
        nodes { id code name }
      }
    }
  }`,
  // 2) Variables.
  {
    storeId: $.data.storeId,
    filter: { isSupplier: true },
  }
);
